const DEFAULT={language:'en',page:'overview',overviewYears:[2023,2024,2025,2026],overviewScale:'raw',replaySplit:'test',replayHorizon:2,replayAnchor:'2026W40',replayDelay:5,replayScore:'clipped',compareSplit:'test',compareHorizon:2,compareScore:'clipped',compareModels:[...MODEL_KEYS],patternYears:[2026],patternSort:'lof',patternWeek:'2026W40',patternTab:'centers',neighborsK:10};
