const model=m=>({persistence:T('Persistence baseline','持续性基线'),clinical_ridge:T('Clinical history','临床岭回归'),combined_ridge:T('Clinical + wastewater','临床＋污水岭回归')}[m]||m);
const splitLabel=x=>({test:T('2026 final test','2026 最终测试'),validation:T('2025 development / validation','2025 开发／验证'),future:T('Unscored snapshot projection','快照末端未评分')}[x]||x);
const scoreLabel=x=>x==='raw'?T('Raw predictions','原始预测'):T('Bounded 0–100%','限制到 0–100%');
const valid=x=>x!==null&&x!==undefined&&Number.isFinite(Number(x));
const fmt=(x,n=3)=>valid(x)?Number(x).toLocaleString(S.language==='zh'?'zh-CN':'en-GB',{minimumFractionDigits:n,maximumFractionDigits:n}):'—';
const pct=x=>valid(x)?fmt(x*100,3)+'%':'—';
const day=x=>String(x||'').slice(0,10);
const week=r=>`${r.anchor_year}W${String(r.anchor_week).padStart(2,'0')}`;
const byDate=(a,b)=>day(a.From||a.anchor_from||a.query_from).localeCompare(day(b.From||b.anchor_from||b.query_from));
const cleanByWeek=Object.fromEntries(D.clean.map(r=>[r.week_key,r]));
const cleanByDate=Object.fromEntries(D.clean.map(r=>[day(r.From),r]));
const addDays=(d,n)=>new Date(Date.parse(day(d)+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);
const labels={ok:['Available','可用'],awaiting_observation:['Awaiting observation','等待目标观测'],missing_query_features:['Missing query features','查询特征缺失'],insufficient_reference:['Insufficient eligible history','历史合格参考不足'],config_not_yet_available:['Before parameter availability','参数尚未固定'],warmup:['Warm-up','预热期'],validation:['Development / validation','开发／验证'],test:['Final test','最终测试'],post_test_monitoring:['After test window','测试期后监测'],frozen_retrospective:['Frozen-snapshot retrospective analysis','冻结版本回顾性分析'],frozen_snapshot_projection:['Frozen snapshot projection','冻结快照末端预测'],'上升':['Rising','上升'],'下降':['Falling','下降'],'持平':['Stable','持平']};
function textValue(v){if(v===null||v===undefined)return '—';if(typeof v==='boolean')return v?T('Yes','是'):T('No','否');if(labels[v])return labels[v][S.language==='zh'?1:0];if(S.language==='en'&&D.cluster_labels_en[v])return D.cluster_labels_en[v];return String(v)}
let exports={},tables={},plots=[],tablePages={},videoState={time:0,paused:true};
