const field=(key,label,options,wide=false)=>`<div class="control ${wide?'wide':''}"><label for="${key}">${E(label)}</label><select id="${key}" data-key="${key}">${options.map(([v,l])=>`<option value="${E(v)}" ${String(S[key])===String(v)?'selected':''}>${E(l)}</option>`).join('')}</select></div>`;
