const checks=(key,label,options)=>`<div class="control wide"><span class="control-label">${E(label)}</span><div class="checks">${options.map(([v,l])=>`<label class="check"><input type="checkbox" data-array="${key}" value="${E(v)}" ${S[key].map(String).includes(String(v))?'checked':''}>${E(l)}</label>`).join('')}</div></div>`;
const stat=(label,value,detail='',compact=false)=>`<div class="stat ${compact?'compact':''}"><span class="stat-label">${E(label)}</span><strong>${E(value)}</strong>${detail?`<small>${E(detail)}</small>`:''}</div>`;
